import * as React from "react";

import { FrameScope } from "../lib/frame-context";
import { cn } from "../lib/utils";
import { EmptyScope } from "./empty";
import { Button } from "./button";
import { Icon } from "./icon";
import { Skeleton } from "./skeleton";
import { toast } from "./sonner";
import { Spinner } from "./spinner";

import styles from "./settings-card.module.css";

export type SettingsCardSaveStatus = "idle" | "saving" | "saved";

export type SettingsCardProps = Omit<
  React.ComponentPropsWithoutRef<"section">,
  "title" | "onSubmit"
> & {
  title: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  dirty?: boolean;
  onSave?: () => void | Promise<unknown>;
  onDiscard?: () => void;
  hint?: React.ReactNode;
  locked?: React.ReactNode;
  loading?: boolean;
  saveLabel?: string;
  /** Blocks Save and says why, the way Button's disabledReason does: the button stays focusable and shows the reason on hover and focus. */
  saveDisabledReason?: string;
  tone?: "default" | "danger";
  actions?: React.ReactNode;
  /** Renders the body edge to edge without the form and footer, for content that is not saved here, such as an embedded DataTable. */
  flush?: boolean;
  /** Progress of a change that saves on its own, shown beside the title. Pass the status from useAutosave. */
  saveStatus?: SettingsCardSaveStatus;
};

const SAVED_VISIBLE_MS = 2000;

/**
 * Saves one setting as soon as it changes, for cards without a Save button. The value updates at once, goes back
 * to the stored one if onSave throws, and an error toast says what failed. Toggles and selects call save(next);
 * a text field calls edit(next) as the user types, save() on blur or Enter and reset() on Escape.
 */
export function useAutosave<T>({
  value,
  onSave,
  errorMessage
}: {
  value: T;
  onSave: (next: T) => void | Promise<unknown>;
  errorMessage: string;
}) {
  const [draft, setDraft] = React.useState(value);
  const [stored, setStored] = React.useState(value);
  const [status, setStatus] = React.useState<SettingsCardSaveStatus>("idle");
  if (!Object.is(value, stored)) {
    setStored(value);
    setDraft(value);
  }
  React.useEffect(() => {
    if (status !== "saved") return undefined;
    const timer = window.setTimeout(() => setStatus("idle"), SAVED_VISIBLE_MS);
    return () => window.clearTimeout(timer);
  }, [status]);
  const pending = status === "saving";
  const save = async (next: T = draft) => {
    if (pending) return;
    setDraft(next);
    if (Object.is(next, stored)) return;
    setStatus("saving");
    try {
      await onSave(next);
      setStatus("saved");
    } catch {
      setDraft(stored);
      setStatus("idle");
      toast.error(errorMessage);
    }
  };
  return { value: draft, edit: setDraft, save, reset: () => setDraft(stored), status, pending };
}

function SaveStatus({ status }: { status: SettingsCardSaveStatus }) {
  return (
    <span className={styles.saveStatus} data-state={status} role="status">
      {status !== "idle" && (
        <>
          <span className={styles.mark} aria-hidden="true" />
          {status === "saving" ? "Saving" : "Saved"}
        </>
      )}
    </span>
  );
}

function FooterStatus({
  hint,
  locked,
  saving,
  dirty
}: {
  hint: React.ReactNode;
  locked: React.ReactNode;
  saving: boolean;
  dirty: boolean;
}) {
  if (locked)
    return (
      <>
        <Icon name="lock" size={14} />
        {locked}
      </>
    );
  if (saving)
    return (
      <>
        <Spinner />
        Saving
      </>
    );
  if (dirty)
    return (
      <>
        <span className={cn(styles.mark, styles.dirtyMark)} aria-hidden="true" />
        Unsaved changes
      </>
    );
  return hint;
}

function Footer({
  hint,
  locked,
  saving,
  dirty,
  loading,
  tone,
  actions,
  onSave,
  onDiscard,
  saveLabel,
  saveDisabledReason
}: Pick<
  SettingsCardProps,
  "hint" | "locked" | "tone" | "actions" | "onSave" | "onDiscard" | "saveDisabledReason"
> & { saving: boolean; dirty: boolean; loading: boolean; saveLabel: string }) {
  return (
    <div className={styles.footer}>
      <p className={styles.status} role="status">
        <FooterStatus hint={hint} locked={locked} saving={saving} dirty={dirty} />
      </p>
      {!locked && (
        <div className={styles.buttons}>
          {tone === "danger" ? (
            actions
          ) : (
            <>
              {dirty && onDiscard && !saving && (
                <Button type="button" variant="ghost" size="sm" onClick={onDiscard}>
                  Discard
                </Button>
              )}
              {onSave && (
                <Button
                  type="submit"
                  variant="primary"
                  size="sm"
                  disabled={!saveDisabledReason && (!dirty || loading)}
                  disabledReason={saveDisabledReason}
                  loading={saving}
                >
                  {saveLabel}
                </Button>
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}

function hasFooterContent({
  hint,
  locked,
  dirty,
  saving,
  tone,
  actions,
  onSave,
  onDiscard
}: Pick<SettingsCardProps, "hint" | "locked" | "tone" | "actions" | "onSave" | "onDiscard"> & {
  dirty: boolean;
  saving: boolean;
}) {
  if (tone === "danger") return Boolean(hint || locked || actions);
  return Boolean(hint || locked || dirty || saving || onSave || (dirty && onDiscard));
}

export function SettingsCard({
  title,
  description,
  action,
  dirty = false,
  onSave,
  onDiscard,
  hint,
  locked,
  loading = false,
  saveLabel = "Save",
  saveDisabledReason,
  tone = "default",
  actions,
  flush = false,
  saveStatus,
  children,
  className,
  ref,
  ...props
}: SettingsCardProps & { ref?: React.Ref<HTMLElement> }) {
  const [saving, setSaving] = React.useState(false);
  const titleId = React.useId();
  const save = async () => {
    if (!onSave || !dirty || saving || locked || saveDisabledReason) return;
    setSaving(true);
    try {
      await onSave();
    } catch {
      // The caller reports the failure with a toast; the card only keeps what was typed.
    } finally {
      setSaving(false);
    }
  };
  const hasFooter = hasFooterContent({ hint, locked, dirty, saving, tone, actions, onSave, onDiscard });
  const header = (
    <div className={styles.header}>
      <div className={styles.titleRow}>
        <h3 id={titleId} className={styles.title}>
          {title}
        </h3>
        {saveStatus && <SaveStatus status={saveStatus} />}
      </div>
      {action && <div className={styles.action}>{action}</div>}
      {description && <p className={styles.description}>{description}</p>}
    </div>
  );
  const body = loading ? <Skeleton lines={2} height={32} /> : children;
  const hasBody = loading || React.Children.toArray(children).length > 0;
  if (flush)
    return (
      <section
        ref={ref}
        data-slot="settings-card"
        data-tone={tone}
        data-flush=""
        aria-labelledby={titleId}
        className={cn(styles.card, className)}
        {...props}
      >
        {header}
        {hasBody && (
          <FrameScope framed>
            <EmptyScope size="sm" fill>
              <div className={styles.flushContent}>{body}</div>
            </EmptyScope>
          </FrameScope>
        )}
      </section>
    );
  return (
    <section
      ref={ref}
      data-slot="settings-card"
      data-tone={tone}
      data-footer={hasFooter ? "" : undefined}
      aria-labelledby={titleId}
      className={cn(styles.card, className)}
      {...props}
    >
      <form
        noValidate
        onSubmit={(event) => {
          event.preventDefault();
          save();
        }}
      >
        {header}
        {hasBody && (
          <FrameScope framed>
            <EmptyScope size="sm" fill={false}>
              <fieldset className={styles.content} disabled={Boolean(locked) || saving}>
                {body}
              </fieldset>
            </EmptyScope>
          </FrameScope>
        )}
        {hasFooter && (
          <Footer
            hint={hint}
            locked={locked}
            saving={saving}
            dirty={dirty}
            loading={loading}
            tone={tone}
            actions={actions}
            onSave={onSave}
            onDiscard={onDiscard}
            saveLabel={saveLabel}
            saveDisabledReason={saveDisabledReason}
          />
        )}
      </form>
    </section>
  );
}
SettingsCard.displayName = "SettingsCard";

.card {
  container-type: inline-size;
  min-width: 0;
  overflow: hidden;
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: 0;
  background: var(--cipher-surface);
  color: var(--cipher-ink);
}
.card[data-tone="danger"] {
  border-color: var(--cipher-bad-line);
}
.header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  column-gap: var(--cipher-space-12);
  row-gap: var(--cipher-space-4);
  padding: var(--cipher-space-surface-inset) var(--cipher-space-surface-inset) 0;
}
.card:not([data-footer]) form > .header:last-child {
  padding-bottom: var(--cipher-space-surface-inset);
}
.titleRow {
  display: flex;
  grid-row: 1;
  grid-column: 1;
  align-items: flex-start;
  gap: var(--cipher-space-8);
  min-width: 0;
}
.title {
  min-width: 0;
  margin: 0;
  padding-block: calc(
    (var(--cipher-size-control-sm) - var(--cipher-type-title-sm-line-height)) /
      2
  );
  font-family: var(--cipher-type-title-sm-font-family);
  font-size: var(--cipher-type-title-sm-font-size);
  line-height: var(--cipher-type-title-sm-line-height);
  font-weight: var(--cipher-type-title-sm-font-weight);
  letter-spacing: var(--cipher-type-title-sm-letter-spacing);
}
.saveStatus {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-6);
  height: var(--cipher-size-control-sm);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.description {
  grid-row: 2;
  grid-column: 1 / -1;
  margin: 0;
  color: var(--cipher-text2);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.action {
  display: flex;
  grid-row: 1;
  grid-column: 2;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-size-control-sm);
}
@container (max-width: 30rem) {
  .header {
    grid-template-columns: minmax(0, 1fr);
  }
  .action {
    grid-row: 2;
    grid-column: 1;
    justify-content: flex-start;
  }
  .action + .description {
    grid-row: 3;
  }
}
.content {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-field-group);
  min-width: 0;
  margin: 0;
  padding: var(--cipher-space-16) var(--cipher-space-surface-inset)
    var(--cipher-space-surface-inset);
  border: 0;
}
.card[data-flush] > .header {
  padding-bottom: var(--cipher-space-16);
}
.flushContent {
  min-width: 0;
  border-top: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.content > [data-slot="field"],
.content > [data-slot="input"] {
  max-width: var(--cipher-size-measure-field);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cipher-space-12);
  min-height: calc(var(--cipher-size-control-sm) + 2 * var(--cipher-space-12));
  padding: var(--cipher-space-12) var(--cipher-space-12) var(--cipher-space-12)
    var(--cipher-space-surface-inset);
  border-top: 1px solid var(--cipher-line-soft);
  background: var(--cipher-paper);
}
.header + .footer {
  margin-top: var(--cipher-space-surface-inset);
}
.card[data-tone="danger"] .footer {
  border-top-color: var(--cipher-bad-line);
  background: var(--cipher-bad-wash);
}
.status {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  min-width: 0;
  margin: 0;
  color: var(--cipher-text2);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.mark {
  flex: none;
  width: var(--cipher-size-unread);
  height: var(--cipher-size-unread);
  border-radius: 0;
  background: var(--cipher-muted);
}
.dirtyMark {
  background: var(--cipher-warn);
}
.saveStatus[data-state="saving"] .mark {
  animation: pulse var(--cipher-duration-slow) ease-in-out infinite alternate;
}
.saveStatus[data-state="saved"] .mark {
  background: var(--cipher-ok);
}
@keyframes pulse {
  to {
    opacity: 0.3;
  }
}
@media (prefers-reduced-motion: reduce) {
  .saveStatus[data-state="saving"] .mark {
    animation: none;
  }
}
.buttons {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-12);
}
